  const installPlaceholderFallback = () => {
    if (window.__matrixPlaceholderFallbackInstalled) return;
    window.__matrixPlaceholderFallbackInstalled = true;

    const placeholderPath = "/placeholder-image.png";
    const officialFallback =
      "https://static.centauro.com.br/store/1-124-3/assets/images/illustration/not-found.svg";
    const isLocalPlaceholder = (value) => {
      if (!value) return false;
      if (value === placeholderPath) return true;
      try {
        const parsed = new URL(value, window.location.href);
        return (
          parsed.origin === window.location.origin &&
          parsed.pathname === placeholderPath &&
          !parsed.search &&
          !parsed.hash
        );
      } catch {
        return false;
      }
    };

    window.addEventListener(
      "error",
      (event) => {
        if (!MOBILE_QUERY.matches) return;
        const image = event.target;
        if (!(image instanceof HTMLImageElement)) return;

        const attempted = image.dataset.matrixPlaceholderFallback === "true";
        const source = image.getAttribute("src") || "";
        const currentSource = image.currentSrc || image.src || "";
        const placeholderFailed =
          isLocalPlaceholder(source) || isLocalPlaceholder(currentSource);
        const officialFailed =
          attempted && (source === officialFallback || currentSource === officialFallback);

        if (!placeholderFailed && !officialFailed) return;
        event.stopImmediatePropagation();

        if (attempted) return;
        image.dataset.matrixPlaceholderFallback = "true";
        image.removeAttribute("srcset");
        image.removeAttribute("sizes");
        image.src = officialFallback;
      },
      true
    );
  };

