  const HOME_PROMOTION_KEY = "matrix:corre4-promotion-deadline:v1";
  const HOME_PROMOTION_DURATION = 15 * 60 * 1000;
  let homePromotionDeadline = 0;
  let homePromotionTimer = 0;

  const syncHomePromotion = (refreshStorage = false) => {
    window.clearTimeout(homePromotionTimer);
    homePromotionTimer = 0;
    if (routeKind() !== "home" || document.hidden) return;
    const section = document.querySelector(".matrix-corre4-grid");
    const heading = section?.querySelector("h2");
    if (!heading) return;

    const now = Date.now();
    if (!homePromotionDeadline || refreshStorage) {
      let saved = 0;
      try { saved = Number(localStorage.getItem(HOME_PROMOTION_KEY)); } catch {}
      if (!Number.isSafeInteger(saved) || saved <= 0 || saved > now + HOME_PROMOTION_DURATION) saved = 0;
      homePromotionDeadline = homePromotionDeadline
        ? Math.min(homePromotionDeadline, saved || homePromotionDeadline)
        : saved || now + HOME_PROMOTION_DURATION;
      if (saved !== homePromotionDeadline) {
        try { localStorage.setItem(HOME_PROMOTION_KEY, String(homePromotionDeadline)); } catch {}
      }
    }

    let badge = section.querySelector(".matrix-home-promotion");
    if (!badge) {
      badge = document.createElement("div");
      badge.className = "matrix-home-promotion";
      badge.innerHTML = `<span class="matrix-home-promotion-label">Promoção termina em</span><span class="matrix-home-promotion-clock"><i aria-hidden="true">${ICONS.stockClock}</i><strong role="timer" aria-label="Tempo restante da promoção" aria-live="off"> </strong></span>`;
      heading.insertAdjacentElement("afterend", badge);
    }
    const seconds = Math.max(0, Math.ceil((homePromotionDeadline - now) / 1000));
    const text = `${String(Math.floor(seconds / 60)).padStart(2, "0")}:${String(seconds % 60).padStart(2, "0")}`;
    // Updating the existing text node avoids a structural Matrix render per tick.
    const textNode = badge.querySelector("strong").firstChild;
    if (textNode.nodeValue !== text) textNode.nodeValue = text;
    const label = badge.querySelector(".matrix-home-promotion-label").firstChild;
    const labelText = seconds ? "Promoção termina em" : "Tempo encerrado";
    if (label.nodeValue !== labelText) label.nodeValue = labelText;
    if (seconds) homePromotionTimer = window.setTimeout(syncHomePromotion, 1000);
  };

