  const setupArenaCarousel = (section) => {
    if (!section || section.dataset.matrixArenaReady === "true") return;
    const track = section.querySelector(".matrix-arena-track");
    const viewport = section.querySelector(".matrix-arena-viewport");
    const slides = [...section.querySelectorAll(".matrix-arena-card")];
    const dots = [...section.querySelectorAll(".matrix-arena-dots [data-arena-slide]")];
    if (!track || !viewport || !slides.length) return;

    let current = 0;
    let pointerStart = null;
    const hydrate = (slide) => {
      const image = slides[slide]?.querySelector("img[data-matrix-deferred-src]");
      if (!image) return;
      image.src = image.dataset.matrixDeferredSrc;
      delete image.dataset.matrixDeferredSrc;
    };
    const sync = (next) => {
      current = (Number(next) + slides.length) % slides.length;
      hydrate(current);
      track.style.setProperty("--matrix-arena-translate", `${current * -100}%`);
      slides.forEach((slide, index) => {
        const active = index === current;
        slide.classList.toggle("is-active", active);
        slide.setAttribute("aria-hidden", active ? "false" : "true");
      });
      dots.forEach((dot, index) => {
        const active = index === current;
        dot.classList.toggle("is-active", active);
        dot.setAttribute("aria-selected", active ? "true" : "false");
      });
      section.dataset.matrixArenaSlide = String(current);
    };
    section.querySelector(".matrix-arena-prev")?.addEventListener("click", () => sync(current - 1));
    section.querySelector(".matrix-arena-next")?.addEventListener("click", () => sync(current + 1));
    dots.forEach((dot, index) => dot.addEventListener("click", () => sync(index)));
    viewport.addEventListener("pointerdown", (event) => {
      pointerStart = event.clientX;
    });
    viewport.addEventListener("pointerup", (event) => {
      if (pointerStart === null) return;
      const distance = event.clientX - pointerStart;
      pointerStart = null;
      if (Math.abs(distance) > 38) sync(current + (distance < 0 ? 1 : -1));
    });
    viewport.addEventListener("pointercancel", () => {
      pointerStart = null;
    });
    viewport.addEventListener("keydown", (event) => {
      if (event.key === "ArrowLeft") {
        event.preventDefault();
        sync(current - 1);
      }
      if (event.key === "ArrowRight") {
        event.preventDefault();
        sync(current + 1);
      }
    });
    section.dataset.matrixArenaReady = "true";
    sync(0);
  };

