    container.addEventListener("pointercancel", finishDrag);
    container.addEventListener("lostpointercapture", () => {
      if (dragState?.moved) suppressClickUntil = performance.now() + 350;
      dragState = null;
      container.classList.remove("is-pointer-dragging");
    });
